func TestFilesService_Add_RetriesRateLimitedStreamingBody(t *testing.T) {
	t.Parallel()

	var bodies []string
	client := newTestClientWithConfig(t, retryTestConfig(), func(w http.ResponseWriter, r *http.Request) {
		body, err := io.ReadAll(r.Body)
		if err != nil {
			t.Fatalf("read request body: %v", err)
		}
		bodies = append(bodies, string(body))
		if len(bodies) == 1 {
			w.WriteHeader(http.StatusTooManyRequests)
			_, _ = w.Write([]byte(`{"error":"rate limited"}`))
			return
		}

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"upload.txt"}}`))
	})

	// A streamed multipart body (built around an *os.File, for example) is
	// not one of the reader types http.NewRequest can replay via GetBody.
	body := io.MultiReader(
		strings.NewReader("--boundary\r\n"),
		strings.NewReader("file bytes\r\n--boundary--\r\n"),
	)
	file, err := client.Files.Add(context.Background(), body, "multipart/form-data; boundary=boundary")
	if err != nil {
		t.Fatalf("Add error: %v", err)
	}
	if file.ID != 12 {
		t.Fatalf("unexpected file: %#v", file)
	}
	if len(bodies) != 2 {
		t.Fatalf("expected 2 attempts, got %d", len(bodies))
	}
	if bodies[0] == "" || bodies[0] != bodies[1] {
		t.Fatalf("expected identical replayed bodies, got %q", bodies)
	}
}

func TestFilesService_AddFile(t *testing.T) {
