package v1

import (
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	"github.com/juhokoskela/pipedrive-go/pipedrive"
)

func newTestClient(t *testing.T, handler http.HandlerFunc) *Client {
	return newTestClientWithConfig(t, pipedrive.Config{}, handler)
}

func newTestClientWithConfig(t *testing.T, cfg pipedrive.Config, handler http.HandlerFunc) *Client {
	t.Helper()

	srv := httptest.NewServer(handler)
	t.Cleanup(srv.Close)

	cfg.BaseURL = srv.URL
	cfg.HTTPClient = srv.Client()

	client, err := NewClient(cfg)
	if err != nil {
		t.Fatalf("NewClient error: %v", err)
	}
	return client
}

// retryTestConfig returns a config whose retry policy retries quickly,
// for tests that exercise retry behavior against a rate-limiting server.
func retryTestConfig() pipedrive.Config {
	policy := pipedrive.DefaultRetryPolicy()
	policy.BaseDelay = time.Millisecond
	policy.MaxDelay = time.Millisecond
	policy.Jitter = func(d time.Duration) time.Duration { return d }
	return pipedrive.Config{RetryPolicy: &policy}
}

