func TestRawClient_Do_SendsQueryAndJSONBody(t *testing.T) {
	t.Parallel()

	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			t.Fatalf("unexpected method: %s", r.Method)
		}
		if r.URL.Path != "/base/items" {
			t.Fatalf("unexpected path: %s", r.URL.Path)
		}
		if got := r.URL.Query()["tag"]; len(got) != 2 || got[0] != "one" || got[1] != "two" {
			t.Fatalf("unexpected query: %s", r.URL.RawQuery)
		}
		if got := r.Header.Get("Accept"); got != "application/json" {
			t.Fatalf("unexpected accept: %q", got)
		}
		if got := r.Header.Get("Content-Type"); got != "application/json" {
			t.Fatalf("unexpected content type: %q", got)
		}

		var payload map[string]string
		if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
			t.Fatalf("decode request: %v", err)
		}
		if payload["name"] != "item" {
			t.Fatalf("unexpected payload: %#v", payload)
		}

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"ok":true}`))
	}))
	t.Cleanup(srv.Close)

	raw, err := NewRawClient(srv.URL+"/base/", srv.Client())
	if err != nil {
		t.Fatalf("NewRawClient error: %v", err)
	}

	var out struct {
		Ok bool `json:"ok"`
	}
	query := url.Values{"tag": {"one", "two"}}
	if err := raw.Do(context.Background(), http.MethodPost, "/items", query, map[string]string{"name": "item"}, &out); err != nil {
		t.Fatalf("Do error: %v", err)
	}
	if !out.Ok {
		t.Fatalf("expected ok")
	}
}

func TestRawClient_Do_RetriesNonReplayableReaderBody(t *testing.T) {
	t.Parallel()

	var bodies []string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, err := io.ReadAll(r.Body)
		if err != nil {
			t.Fatalf("read request body: %v", err)
		}
		bodies = append(bodies, string(body))
		if len(bodies) == 1 {
			w.WriteHeader(http.StatusTooManyRequests)
			_, _ = w.Write([]byte(`{"error":"rate limited"}`))
			return
		}

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"ok":true}`))
	}))
	t.Cleanup(srv.Close)

	policy := DefaultRetryPolicy()
	policy.BaseDelay = time.Millisecond
	policy.MaxDelay = time.Millisecond
	policy.Jitter = func(d time.Duration) time.Duration { return d }
	httpClient := NewHTTPClient(Config{
		HTTPClient:  srv.Client(),
		RetryPolicy: &policy,
	})

	raw, err := NewRawClient(srv.URL, httpClient)
	if err != nil {
		t.Fatalf("NewRawClient error: %v", err)
	}

	var out struct {
		Ok bool `json:"ok"`
	}
	// MultiReader is not one of the types http.NewRequest gives a GetBody,
	// so without buffering the body it can never be replayed on retry.
	body := io.MultiReader(strings.NewReader("part-one,"), strings.NewReader("part-two"))
	if err := raw.Do(context.Background(), http.MethodPost, "/files", nil, body, &out); err != nil {
		t.Fatalf("Do error: %v", err)
	}
	if !out.Ok {
		t.Fatalf("expected ok")
	}
	if len(bodies) != 2 {
		t.Fatalf("expected 2 attempts, got %d", len(bodies))
	}
	if bodies[0] != "part-one,part-two" || bodies[1] != bodies[0] {
		t.Fatalf("expected identical replayed bodies, got %q", bodies)
	}
}

