package multipartbody

import (
	"mime/multipart"
	"net/url"
	"strings"
	"testing"
)

func TestNewFile_EncodesReplayableBody(t *testing.T) {
	t.Parallel()

	contentType, body, err := NewFile("file", "upload.txt", strings.NewReader("content"))
	if err != nil {
		t.Fatalf("NewFile error: %v", err)
	}
	if !strings.HasPrefix(contentType, "multipart/form-data; boundary=") {
		t.Fatalf("unexpected content type: %q", contentType)
	}

	// *bytes.Reader is what http.NewRequest needs to install a GetBody,
	// which is what makes the body replayable for retries.
	first, err := body.ReadString(0)
	if err == nil || first != "" {
		t.Fatalf("expected no NUL byte, got %q", first)
	}
	if _, err := body.Seek(0, 0); err != nil {
		t.Fatalf("expected seekable body: %v", err)
	}

	if _, _, err := NewFile("", "upload.txt", strings.NewReader("content")); err == nil {
		t.Fatalf("expected error for missing field name")
	}
	if _, _, err := NewFile("file", "", strings.NewReader("content")); err == nil {
		t.Fatalf("expected error for missing file name")
	}
	if _, _, err := NewFile("file", "upload.txt", nil); err == nil {
		t.Fatalf("expected error for missing content")
	}
}

func TestNewFileWithFields_EncodesFieldsBeforeFile(t *testing.T) {
	t.Parallel()

	fields := url.Values{
		"deal_id": {"7"},
		"lead_id": {"0d9717c6-b4e7-4d3b-9b5d-e80f7d5c1a2b"},
	}

	contentType, body, err := NewFileWithFields("file", "upload.txt", strings.NewReader("content"), fields)
	if err != nil {
		t.Fatalf("NewFileWithFields error: %v", err)
	}
	if !strings.HasPrefix(contentType, "multipart/form-data; boundary=") {
		t.Fatalf("unexpected content type: %q", contentType)
	}

	reader := multipart.NewReader(body, strings.TrimPrefix(contentType, "multipart/form-data; boundary="))
	form, err := reader.ReadForm(1 << 20)
	if err != nil {
		t.Fatalf("parse multipart body: %v", err)
	}
	if got := form.Value["deal_id"]; len(got) != 1 || got[0] != "7" {
		t.Fatalf("unexpected deal_id: %v", got)
	}
	if got := form.Value["lead_id"]; len(got) != 1 || got[0] != "0d9717c6-b4e7-4d3b-9b5d-e80f7d5c1a2b" {
		t.Fatalf("unexpected lead_id: %v", got)
	}

	fileHeader := form.File["file"]
	if len(fileHeader) != 1 || fileHeader[0].Filename != "upload.txt" {
		t.Fatalf("unexpected file part: %#v", fileHeader)
	}
	file, err := fileHeader[0].Open()
	if err != nil {
		t.Fatalf("open file part: %v", err)
	}
	defer file.Close()
	if content, err := readAll(file); err != nil || content != "content" {
		t.Fatalf("unexpected file content: %q (%v)", content, err)
	}
}

func TestNewFileWithFields_NoFieldsMatchesNewFile(t *testing.T) {
	t.Parallel()

	contentType, body, err := NewFileWithFields("file", "upload.txt", strings.NewReader("content"), nil)
	if err != nil {
		t.Fatalf("NewFileWithFields error: %v", err)
	}

	wantType, wantBody, err := NewFile("file", "upload.txt", strings.NewReader("content"))
	if err != nil {
		t.Fatalf("NewFile error: %v", err)
	}
	if contentType != wantType {
		t.Fatalf("content type mismatch: %q vs %q", contentType, wantType)
	}
	if !body.Equal(wantBody) {
		t.Fatalf("body mismatch: %q vs %q", body.String(), wantBody.String())
	}
}

func readAll(r interface{ Read([]byte) (int, error) }) (string, error) {
	var sb strings.Builder
	buf := make([]byte, 32)
	for {
		n, err := r.Read(buf)
		if n > 0 {
			sb.Write(buf[:n])
		}
		if err != nil {
			if err.Error() == "EOF" {
				return sb.String(), nil
			}
			return sb.String(), err
		}
	}
}

